import * as T from './vendor/three.module.js';
const canvas=document.querySelector('#workspace'),status=document.querySelector('#scene-status'),reduced=matchMedia('(prefers-reduced-motion: reduce)'),label=document.querySelector('#object-label');
const worldEnglish={"3D nicht verfügbar · Alle Stationen bleiben erreichbar": "3D unavailable · All stations remain accessible", "3D pausiert · Bitte die Stationsschaltflächen nutzen": "3D paused · Please use the station buttons", "Ziehen zum Drehen · Bildschirm wählen · Station wechseln": "Drag to orbit · Select a screen · Switch stations", "Animation fortsetzen": "Resume ambient motion", "Animation pausieren": "Pause ambient motion", "Born2beroot öffnen": "Open Born2beroot", "Inception öffnen": "Open Inception", "Geplanten Lernpfad öffnen": "Open the planned learning path", "Profil öffnen": "Open profile", "Kontakt öffnen": "Open contact", "MAYACHE / IT-SYSTEMINTEGRATION": "MAYACHE / IT SYSTEM INTEGRATION", "TLS / Volumes / Netzwerke": "TLS / Volumes / Networks", "INFRASTRUKTUR-LAB": "INFRASTRUCTURE LAB", "GEPLANT / NOCH NICHT UMGESETZT": "PLANNED / NOT IMPLEMENTED", "ZIEL: IT-SYSTEMINTEGRATION": "GOAL: IT SYSTEM INTEGRATION", "Linux / Container / Netzwerke": "Linux / Containers / Networks", "KONTAKT": "CONTACT", "Berufseinstieg in Deutschland": "Starting a career in Germany"};
const worldText=text=>document.documentElement.lang==='en'?(worldEnglish[text]||text):text;
let sceneMessage='Ziehen zum Drehen · Bildschirm wählen · Station wechseln';
function showStatus(message=sceneMessage){sceneMessage=message;status.textContent=worldText(message);}
document.addEventListener('worldlanguage',()=>showStatus());
let renderer;
function fallback(message){canvas.hidden=true;document.querySelector('#world-fallback').hidden=false;showStatus(message);document.querySelectorAll('.world-controls button').forEach(b=>b.disabled=true);}
try{renderer=new T.WebGLRenderer({canvas,antialias:true,powerPreference:'low-power'});}catch{fallback('3D nicht verfügbar · Alle Stationen bleiben erreichbar');}
if(renderer)start();
function start(){
renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.35;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;
const scene=new T.Scene();scene.background=new T.Color('#070c16');scene.fog=new T.FogExp2('#070c16',.023);
const camera=new T.PerspectiveCamera(43,1,.1,150),world=new T.Group();scene.add(world);
scene.add(new T.HemisphereLight(0xb4e5f5,0x152235,2.3));const sun=new T.DirectionalLight(0xdefcf3,3.5);sun.position.set(-8,16,10);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);Object.assign(sun.shadow.camera,{left:-20,right:20,top:20,bottom:-20});sun.shadow.normalBias=.03;scene.add(sun);
const mint=new T.MeshStandardMaterial({color:0x9bf7d3,emissive:0x4deab1,emissiveIntensity:1.4,roughness:.35});
const blue=new T.MeshStandardMaterial({color:0x8ec9ff,emissive:0x386dcf,emissiveIntensity:1.4});
const metal=new T.MeshStandardMaterial({color:0x243b4c,metalness:.65,roughness:.38}),dark=new T.MeshStandardMaterial({color:0x101d2c,metalness:.45,roughness:.5}),rim=new T.MeshStandardMaterial({color:0x49647b,metalness:.7,roughness:.3});
const interact=[],floaters=[],routes=[],spin=[],screens=[];
function box(w,h,d,m,x,y,z,parent=world){const o=new T.Mesh(new T.BoxGeometry(w,h,d),m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
function edges(o){o.add(new T.LineSegments(new T.EdgesGeometry(o.geometry),new T.LineBasicMaterial({color:0x7eb9c8,transparent:true,opacity:.28})));}
function cylinder(radius,height,m,x,y,z,parent=world){const o=new T.Mesh(new T.CylinderGeometry(radius,radius,height,64),m);o.position.set(x,y,z);o.receiveShadow=true;o.castShadow=true;parent.add(o);return o;}
function textTexture(lines,accent='#9bf7d3',image){const c=document.createElement('canvas');c.width=1024;c.height=640;const ctx=c.getContext('2d');ctx.fillStyle='#0c1a29';ctx.fillRect(0,0,1024,640);ctx.strokeStyle='#365563';ctx.strokeRect(18,18,988,604);ctx.fillStyle=accent;ctx.font='20px Consolas,monospace';ctx.fillText(worldText('MAYACHE / IT-SYSTEMINTEGRATION'),48,66);lines.forEach((s,i)=>{ctx.fillStyle=i===0?'#edf8ff':i===1?accent:'#89a5ba';ctx.font=i===0?'bold 66px Segoe UI':'28px Segoe UI';ctx.fillText(worldText(s),48,170+i*80);});ctx.fillStyle=accent;for(let i=0;i<11;i++)ctx.fillRect(48+i*84,550,50,4);const tex=new T.CanvasTexture(c);tex.colorSpace=T.SRGBColorSpace;if(image){new T.TextureLoader().load(image,t=>{ctx.drawImage(t.image,48,290,928,285);tex.needsUpdate=true;request();});}return tex;}
function panel(lines,x,y,z,width=3.5,accent,image,parent=world){const g=new T.Group();g.position.set(x,y,z);parent.add(g);edges(box(width+.13,width*.625+.13,.14,rim,0,0,0,g));const mesh=new T.Mesh(new T.PlaneGeometry(width,width*.625),new T.MeshBasicMaterial({map:textTexture(lines,accent,image)}));mesh.position.z=.078;g.add(mesh);screens.push({mesh,lines,accent,image});return g;}
function hit(group,id,title,type='project'){group.traverse(o=>{if(o.isMesh){o.userData={id,title,type};interact.push(o);}});}
function platform(x,z,r=3.7){const g=new T.Group();g.position.set(x,0,z);world.add(g);edges(cylinder(r,.3,metal,0,-.3,0,g));cylinder(r-.15,.1,dark,0,-.09,0,g);const ring=new T.Mesh(new T.TorusGeometry(r-.02,.023,8,100),mint);ring.rotation.x=Math.PI/2;ring.position.y=-.12;g.add(ring);return g;}
// A walkable-looking collection of floating stations, all built as real geometry.
const station=platform(0,0,4.5);
const monitor=panel(['Born2beroot','DEBIAN / SSH / UFW','VirtualBox / cron-Monitoring'],.5,2.25,-.5,3.5,'#9bf7d3',null,station);box(.18,1.1,.18,metal,.5,.65,-.5,station);box(1.5,.08,.75,rim,.5,.14,-.4,station);hit(monitor,'born2beroot','Born2beroot öffnen');
const second=panel(['Inception','DOCKER COMPOSE','Nginx / WordPress / MariaDB','TLS / Volumes / Netzwerke'],-2.4,1.65,.5,2.35,'#8ec9ff',null,station);second.rotation.y=.45;hit(second,'inception','Inception öffnen');
const keyboard=box(2.1,.09,.72,metal,.5,.18,1.4,station);edges(keyboard);const keys=new T.InstancedMesh(new T.BoxGeometry(.12,.04,.1),rim,44),dummy=new T.Object3D();let n=0;for(let row=0;row<4;row++)for(let col=0;col<11;col++){dummy.position.set(-.38+col*.17,.26,1.17+row*.15);dummy.updateMatrix();keys.setMatrixAt(n++,dummy.matrix);}station.add(keys);
for(let i=0;i<3;i++){box(.9,.45,1.1,metal,3,.4+i*.51,-.6,station);for(let j=0;j<3;j++)box(.05,.04,.03,mint,2.75+j*.13,.4+i*.51,-.03,station);}
const systems=platform(9,-5,3.8);
const core=new T.Group();core.position.set(0,2.1,0);systems.add(core);const crystal=new T.Mesh(new T.IcosahedronGeometry(.85,1),new T.MeshStandardMaterial({color:0x5adac3,metalness:.6,roughness:.12,emissive:0x207f76,emissiveIntensity:.8,wireframe:true}));core.add(crystal);spin.push(crystal);floaters.push(core);hit(core,'lab','Geplanten Lernpfad öffnen');
for(let i=0;i<3;i++){const torus=new T.Mesh(new T.TorusGeometry(1.4+i*.2,.025,8,90),i===1?blue:mint);torus.rotation.set(.4+i*.6,.5+i*.8,0);core.add(torus);spin.push(torus);}
for(let i=0;i<6;i++){const a=i*Math.PI/3,x=Math.cos(a)*2.6,z=Math.sin(a)*2.6;for(let j=0;j<3;j++){edges(box(.7,.38,.8,metal,x,.3+j*.44,z,systems));box(.05,.05,.02,i%2?blue:mint,x+.2,.3+j*.44,z+.41,systems);}}
const labSign=panel(['INFRASTRUKTUR-LAB','Infrastructure Lab','GEPLANT / NOCH NICHT UMGESETZT'],0,1.4,2.3,2.1,'#9bf7d3',null,systems);hit(labSign,'lab','Geplanten Lernpfad öffnen');
const about=platform(-8,-6,3.2);const profile=panel(['MAYACHE','Mohamed Yassine Ayache','ZIEL: IT-SYSTEMINTEGRATION','Linux / Container / Netzwerke'],0,2,0,3.3,'#d7bcff',null,about);hit(profile,'about','Profil öffnen','view');
for(let i=0;i<4;i++){const o=box(.55,.55,.55,i%2?rim:metal,Math.sin(i*2)*2.3,.8+i*.48,Math.cos(i*2)*1.3,about);o.rotation.set(.3,.5,.2);floaters.push(o);}
const contact=platform(2,-12,3.4);const portal=new T.Group();portal.position.y=2.2;contact.add(portal);for(let i=0;i<3;i++){const ring=new T.Mesh(new T.TorusGeometry(1.75+i*.11,.045,10,100),i===1?rim:mint);ring.position.z=-i*.15;portal.add(ring);}const contactPanel=panel(['KONTAKT','Berufseinstieg in Deutschland'],0,2.2,.22,2.7,'#9bf7d3',null,contact);hit(contactPanel,'contact','Kontakt öffnen','view');
// Suspended data paths make the relationships between destinations visible.
[[[0,.2,-2],[3,.7,-3],[6,.7,-3],[9,.2,-5]],[[0,.2,-2],[-3,.8,-4],[-6,.8,-3],[-8,.2,-6]],[[0,.2,-2],[0,.8,-6],[4,.8,-8],[2,.2,-12]]].forEach((pts,i)=>{const curve=new T.CatmullRomCurve3(pts.map(p=>new T.Vector3(...p)));world.add(new T.Mesh(new T.TubeGeometry(curve,70,.025,6),new T.MeshBasicMaterial({color:0x386a78,transparent:true,opacity:.7})));const dot=new T.Mesh(new T.SphereGeometry(.065,10,10),i===1?blue:mint);world.add(dot);routes.push({curve,dot});});
const grid=new T.GridHelper(100,100,0x294758,0x142b3b);grid.position.y=-1.3;scene.add(grid);
const particles=new Float32Array(240*3);let seed=31;function random(){seed=seed*16807%2147483647;return(seed-1)/2147483646;}for(let i=0;i<particles.length;i+=3){particles[i]=(random()-.5)*70;particles[i+1]=random()*20-3;particles[i+2]=(random()-.5)*65;}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.BufferAttribute(particles,3));scene.add(new T.Points(geo,new T.PointsMaterial({color:0xa0d2e0,size:.035,transparent:true,opacity:.7})));
const glow=new T.PointLight(0x52f5c3,60,28);glow.position.set(8,4,-5);scene.add(glow);const violet=new T.PointLight(0xa188ff,35,18);violet.position.set(-8,4,-5);scene.add(violet);
const views={home:{p:[15,12,22],t:[0,0,-3]},work:{p:[6.5,5.7,10],t:[0,1,0]},systems:{p:[15,5.5,6],t:[9,1,-5]},about:{p:[-1,5.5,5],t:[-8,1,-6]},contact:{p:[8,5,0],t:[2,1,-12]}};
let view=document.body.dataset.view||'home',paused=reduced.matches,elapsed=0,last=performance.now(),frame,dragging=false,moved=0,x=0,y=0,orbit=0,targetOrbit=0,contextLost=false;
const targetPos=new T.Vector3(),targetLook=new T.Vector3(),look=new T.Vector3(),base=new T.Vector3();
function setDestination(name){view=views[name]?name:'home';orbit=targetOrbit=0;updateTarget();canvas.dataset.destination=view;if(reduced.matches){camera.position.copy(targetPos);look.copy(targetLook);}request();}
function updateTarget(){const v=views[view],mobile=innerWidth<600;base.fromArray(v.p);targetLook.fromArray(v.t);if(mobile){base.sub(targetLook).multiplyScalar(1.12).add(targetLook);targetLook.y-=.2;}const offset=base.clone().sub(targetLook);offset.applyAxisAngle(new T.Vector3(0,1,0),orbit);targetPos.copy(targetLook).add(offset);}
function render(now){frame=null;if(contextLost)return;const dt=Math.min((now-last)/1000,.05);last=now;if(!paused)elapsed+=dt;orbit=T.MathUtils.damp(orbit,targetOrbit,7,dt);updateTarget();const smooth=reduced.matches?1:1-Math.exp(-dt*5);camera.position.lerp(targetPos,smooth);look.lerp(targetLook,smooth);camera.lookAt(look);camera.setViewOffset(canvas.width,canvas.height,innerWidth<600?0:-canvas.width*.19,innerWidth<600?canvas.height*.17:0,canvas.width,canvas.height);floaters.forEach((o,i)=>{o.userData.baseY??=o.position.y;o.position.y=o.userData.baseY+(paused?0:Math.sin(elapsed*.8+i)*.12);});spin.forEach((o,i)=>{if(!paused){o.rotation.y+=dt*(.15+i*.025);o.rotation.z+=dt*.06;}});routes.forEach((r,i)=>r.dot.position.copy(r.curve.getPointAt((elapsed*.13+i*.3)%1)));renderer.render(scene,camera);canvas.dataset.renderWidth=String(innerWidth);canvas.dataset.camera=camera.position.toArray().map(n=>n.toFixed(2)).join(',');const moving=camera.position.distanceTo(targetPos)>.005||look.distanceTo(targetLook)>.005||Math.abs(orbit-targetOrbit)>.001;if(!document.hidden&&(!paused||moving))frame=requestAnimationFrame(render);}
function request(){if(!frame&&!document.hidden&&!contextLost){last=performance.now()-16;frame=requestAnimationFrame(render);}}
function resize(){renderer.setSize(innerWidth,innerHeight,false);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();updateTarget();request();}window.addEventListener('resize',resize);
document.addEventListener('worldnavigate',e=>setDestination(e.detail));
function rotate(amount){targetOrbit=T.MathUtils.clamp(targetOrbit+amount,-.9,.9);request();}document.querySelector('#rotate-left').onclick=()=>rotate(-.25);document.querySelector('#rotate-right').onclick=()=>rotate(.25);document.querySelector('#reset-scene').onclick=()=>setDestination(view);
const pause=document.querySelector('#pause-scene');function showPause(){pause.setAttribute('aria-pressed',String(paused));pause.setAttribute('aria-label',worldText(paused?'Animation fortsetzen':'Animation pausieren'));pause.textContent=paused?'▷':'Ⅱ';}showPause();pause.onclick=()=>{paused=!paused;showPause();request();};reduced.addEventListener('change',e=>{paused=e.matches;showPause();setDestination(view);});
const ray=new T.Raycaster(),pointer=new T.Vector2();function pick(e){const b=canvas.getBoundingClientRect();pointer.set((e.clientX-b.left)/b.width*2-1,-(e.clientY-b.top)/b.height*2+1);ray.setFromCamera(pointer,camera);return ray.intersectObjects(interact,false)[0]?.object.userData;}
canvas.addEventListener('pointerdown',e=>{dragging=true;moved=0;x=e.clientX;y=e.clientY;canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(dragging){moved+=Math.abs(e.clientX-x)+Math.abs(e.clientY-y);rotate((e.clientX-x)*.005);x=e.clientX;y=e.clientY;label.classList.remove('show');}else{const item=pick(e);label.textContent=worldText(item?.title||'');label.classList.toggle('show',!!item);label.style.left=Math.min(e.clientX+15,innerWidth-210)+'px';label.style.top=e.clientY+18+'px';canvas.style.cursor=item?'pointer':'grab';}});canvas.addEventListener('pointerup',e=>{if(!dragging)return;dragging=false;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);if(moved>8)return;const item=pick(e);if(item){if(item.type==='view')location.hash=item.id;else document.dispatchEvent(new CustomEvent('projectselect',{detail:item.id}));}});canvas.addEventListener('pointercancel',()=>dragging=false);canvas.addEventListener('pointerleave',()=>label.classList.remove('show'));
canvas.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();rotate(e.key==='ArrowLeft'?-.25:.25);}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&frame){cancelAnimationFrame(frame);frame=null;}else request();});
canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();contextLost=true;if(frame)cancelAnimationFrame(frame);frame=null;fallback('3D pausiert · Bitte die Stationsschaltflächen nutzen');});canvas.addEventListener('webglcontextrestored',()=>{contextLost=false;canvas.hidden=false;document.querySelector('#world-fallback').hidden=true;document.querySelectorAll('.world-controls button').forEach(b=>b.disabled=false);showStatus('Ziehen zum Drehen · Bildschirm wählen · Station wechseln');request();});
document.addEventListener('worldlanguage',()=>{screens.forEach(s=>{const old=s.mesh.material.map;s.mesh.material.map=textTexture(s.lines,s.accent,s.image);old.dispose();});label.classList.remove('show');showPause();request();});
updateTarget();camera.position.copy(targetPos);look.copy(targetLook);resize();setDestination(view);canvas.dataset.ready='true';showStatus('Ziehen zum Drehen · Bildschirm wählen · Station wechseln');request();
}
